void InsightsStats::PublishQueryProfilesToPulse(
  const string& stat_type_name,
  Function<void()> done_cb) {

auto put_arg = make_shared<PutMetricDataArg>();
  for (const auto& hash_vec : query_shape_map_) {
    // Whatever aggregation/downsampling logic here. At first,
    // will just insert the query hash and expression.
    // According to Pulse docs, the first attribute is used
    // as the unique key/ID field.
    // TODO: find out if this is okay. The hash field won't be
    // unique, but the <timestamp, hash> pair should be.
    for (const auto& profile : hash_vec) {
       // timestamp set implicitly.
      NusightsStat stat(stat_type_name);
      stat.AddAttribute("hash", hash_vec.first);
      stat.AddAttribute("expr", hash_vec.second->query_expr);
      stat.AddAttribute("latency", hash_vec.second->latency);
      stat.AddStatsToPutMetricDataArg(put_arg.get());
    }
  }
  pulse_interface_->PutMetricData(put_arg, done_cb);
}

