bool InsightsNodeQuery::EvaluateComparisonExpression(
  const ComparisonExpression& expr,
  const EntityKey& entity_guid,
  bool& metric_data_missing) {

  const auto& column = expr.lhs().leaf().column();
  const auto& value = expr.rhs().leaf().value();

  if (column.empty()) {
    return EvaluateWildcardComparisonExpression(expr, entity_guid);
  } else if (IsAncestor(column)) {
    return EvaluateEntityTypeExpression(expr, entity_guid);
  } else {



    // Metric / attribute comparison expression.
    if (InsightsUtil::IsDataValueInitialized(value)) {
      return EvaluateMetricExpression(expr, entity_guid, metric_data_missing);
