      DCHECK(op == ComparisonExpression::kEQ ||
             op == ComparisonExpression::kNE)
          << "Invalid operator in attribute existence check : "
          << ComparisonExpression_Operator_Name(op);

      auto emkey = make_tuple(entity_guid.first, entity_guid.second, column);
      auto col_missing =
        (filter_metric_values_.find(emkey) == filter_metric_values_.end());
