[IDF Design Documents | Query semantics for filter clause]
## Table
bool InsightsNodeQuery::EvaluateBooleanExpression(
  const BooleanExpression& expr,
  const EntityKey& entity_guid,
  bool& metric_data_missing) {

  if (expr.has_comparison_expr()) {
    return EvaluateComparisonExpression(expr.comparison_expr(),
                                        entity_guid,
                                        metric_data_missing);
  } else {
    bool lhs = EvaluateBooleanExpression(expr.lhs(), entity_guid,
                                         metric_data_missing);
    if (QueryHasError()) {
      return false;
    }

    if (expr.operator_() == BooleanExpression::kOr) {
      return lhs || EvaluateBooleanExpression(expr.rhs(), entity_guid,
                                              metric_data_missing);
    } else if (expr.operator_() == BooleanExpression::kAnd) {
      return lhs && EvaluateBooleanExpression(expr.rhs(), entity_guid,
                                              metric_data_missing);
    } else {
      DCHECK_EQ(expr.operator_(), BooleanExpression::kNot);
      return !lhs;
    }
  }
}

