## Implementation Details:
Single global lock across all data (vs. per shard lock in the “Alternative solution” section)

## RPCs To Be Implemented / Updated:
WriteLock
message WriteLockArg {
// Required. This field can either be specified by the client, or filled by the replica
// using the cluster_uuid as the credential.
optional string lock_id = 0; [NO LONGER NEEDED]
}
message WriteLockRet {
optional string lock_id = 0;
// ‘ttl_msecs’ is the period of time the lock will be held, after which the lock will be automatically released by IDF server.
// Here we return the ttl instead of the expiration timestamp as to avoid the dependency
// on IDF and clients have the same system time.
optional int64 ttl_msecs = 1;
}
WriteUnlock
message WriteUnlockArg {
// Required.
optional string lock_id = 0;
}
message WriteUnlockRet {
}
NodeWriteLock
message NodeWriteLockArg {
// Required.
optional string lock_id = 0;
// Shards belonging to the processing node.
repeated uint32 shard_id_list = 1;
}
message NodeWriteLockRet {
}
Write Operations
message UpdateEntityArg / DeleteEntityArg {
...
optional string lock_id = x;
}
LockState
enum LockState {
kUnlocked;
kLockInProgress; // This is needed for leadership transfer recovery.
kLocked;
}

